   '[{"id":"a","text":"Overstocking"},{"id":"b","text":"Selective grazing"},{"id":"c","text":"Fencing"},{"id":"d","text":"Proper stocking rate"}]'::jsonb, 'd'),
  ('fp-g00150', 'forest-production', 'range-management', 'Easy', 'practice',
   'What does RA 7586, the NIPAS Act, focus on with regards to rangelands?',
