   '[{"id":"a","text":"Increasing the immediate biomass production"},{"id":"b","text":"Ensuring even distribution of livestock"},{"id":"c","text":"Maximizing livestock density at all times"},{"id":"d","text":"Allowing vegetation to reach seed maturity before grazing"}]'::jsonb, 'd'),
