  ('fp-g00162', 'forest-production', 'range-management', 'Medium', 'practice',
   'Which of the following is a critical component in determining the carrying capacity of a rangeland?',
   '[{"id":"a","text":"Soil type and fertility"},{"id":"b","text":"Annual rainfall and climate patterns"},{"id":"c","text":"Livestock breed used"},{"id":"d","text":"Proximity to water sources"}]'::jsonb, 'b'),
  ('fp-g00163', 'forest-production', 'range-management', 'Medium', 'practice',
   'What is the primary purpose of implementing rest periods in rotational grazing systems?',
   '[{"id":"a","text":"To increase livestock productivity immediately"},{"id":"b","text":"To reduce labor costs associated with grazing management"},{"id":"c","text":"To maximize short-term forage availability"},{"id":"d","text":"To restore plant vigor and health"}]'::jsonb, 'd'),
  ('fp-g00164', 'forest-production', 'range-management', 'Medium', 'practice',
